package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamDiseaseAyurvedaBank2 {
    private const val T = "බෝවන හා බෝ නොවන රෝග, ප්‍රජා සෞඛ්‍යය හා හෙළ වෙදකම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("බෝ නොවන රෝග (Non-Communicable Diseases — NCDs) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පුද්ගලයෙකුගෙන් තවත් පුද්ගලයෙකුට ක්ෂුද්‍රජීවීන් මගින් බෝ නොවන, ජීවන රටාව හා ජාන සම්බන්ධ නිදන්ගත රෝගයි", "මදුරුවන්ගෙන් බෝවන රෝගයි", "එක් දිනකින් සම්පූර්ණයෙන් සුව වන රෝගයි", "බැක්ටීරියා මගින් ඇතිවන රෝගයි", "හෘද රෝග, දියවැඩියාව, පිළිකා සහ නිදන්ගත ශ්වසන රෝග ප්‍රධාන බෝ නොවන රෝග 4 වේ."),
        q("දෙවන වර්ගයේ දියවැඩියාව (Type 2 Diabetes Mellitus) ඇතිවීමට ප්‍රධාන හේතුව කුමක්ද?", "ශරීරයේ සෛල ඉන්සියුලින් හෝමෝනයට ප්‍රතිරෝධී වීම (Insulin Resistance) හෝ ප්‍රමාණවත් ඉන්සියුලින් නොමැති වීම", "විටමින් C ඌනතාව", "බැක්ටීරියා ආසාදනය", "අයඩීන් හිඟකම", "අධික සීනි හා පිටි ආහාර, තරබාරුකම සහ ව්‍යායාම මඳකම Type 2 දියවැඩියාවට මුල පුරයි."),
        q("නිරාහාරව පැය 8-10ක් සිටීමෙන් පසු පරීක්ෂා කරන සාමාන්‍ය රුධිර ග්ලූකෝස් (Fasting Blood Sugar) මට්ටම කොපමණ විය යුතුද?", "70 mg/dL සිට 99 mg/dL දක්වා (100 mg/dL ට අඩු)", "150 mg/dL සිට 200 mg/dL දක්වා", "250 mg/dL ට වැඩි", "30 mg/dL ට අඩු", "නිරාහාර රුධිර සීනි මට්ටම 126 mg/dL හෝ ඊට වැඩි නම් එය දියවැඩියා රෝගී තත්ත්වයක් ලෙස හඳුනාගනී."),
        q("දියවැඩියා රෝගියෙකුගේ පසුගිය මාස 3ක සාමාන්‍ය රුධිර සීනි පාලනය මැන බැලීමට භාවිත කරන නිවැරදිම රුධිර පරීක්ෂණය කුමක්ද?", "HbA1c පරීක්ෂණය (Glycated Hemoglobin)", "සෙම පරීක්ෂණය", "X-රේ පරීක්ෂණය", "මලපහ පරීක්ෂණය", "HbA1c අගය 6.5%ට අඩුවෙන් පවත්වා ගැනීම දියවැඩියා අතුරු ආබාධ වළක්වා ගැනීමට වැදගත් වේ."),
        q("පාලනය නොකළ දිගුකාලීන දියවැඩියාව නිසා ඇතිවිය හැකි බරපතළ ද්විතියික සංකූලතා මොනවාද?", "වකුගඩු අකර්මණ්‍ය වීම, ඇස් පෙනීම නැති වීම (Retinopathy) සහ පාදවල තුවාල සුව නොවීම", "උස වැඩිවීම", "හිසකෙස් වර්ධනය", "අස්ථි දැඩි වීම", "අධික රුධිර සීනි ස්නායු හා කුඩා රුධිර වාහිනී විනාශ කරන බැවින් වකුගඩු, ඇස් සහ හෘදයට හානි කරයි."),
        q("'නිහඬ මාරයා' (Silent Killer) ලෙස වෛද්‍ය විද්‍යාවේ හඳුන්වනු ලබන, බොහෝ විට මූලික රෝග ලක්ෂණ නොපෙන්වන බෝ නොවන රෝගය කුමක්ද?", "අධි රුධිර පීඩනය (Hypertension)", "පැපොල", "කම්මුල්ගාය", "ඇස් රුදාව", "කිසිදු ලක්ෂණයක් නොමැතිව රුධිර පීඩනය ඉහළ ගොස් හදිසියේම ආඝාතය හෝ හෘදයාබාධය ඇති කරන බැවින් මෙසේ හැඳින්වේ."),
        q("වැඩිහිටියෙකුගේ සාමාන්‍ය ප්‍රශස්ත රුධිර පීඩන අගය කොපමණද?", "120/80 mmHg ට අඩු (සිස්ටොලික් < 120, ඩයස්ටොලික් < 80)", "160/100 mmHg", "80/40 mmHg", "200/120 mmHg", "රුධිර පීඩනය අඛණ්ඩව 140/90 mmHg හෝ ඊට වැඩි නම් එය අධි රුධිර පීඩනය ලෙස සැලකේ."),
        q("දෛනික ආහාරයේ ලුණු (සෝඩියම්) පරිභෝජනය අඩු කිරීම සෘජුවම පාලනය කිරීමට උපකාරී වන රෝගය කුමක්ද?", "අධි රුධිර පීඩනය", "රාත්‍රී අන්ධතාව", "ඩෙංගු උණ", "මී උණ", "WHO නිර්දේශය අනුව වැඩිහිටියෙකු දිනකට ලුණු ග්‍රෑම් 5කට (තේ හැඳි 1කට) වඩා අඩුවෙන් ගත යුතුය."),
        q("හෘදයට රුධිරය සපයන කිරීටක ධමනි තුළ මේදය (කොලෙස්ටරෝල්) තැන්පත් වී ධමනි පටු වීමේ ක්‍රියාවලිය කුමක්ද?", "ධමනි සිහින් වීම හෙවත් ඇතරොස්ක්ලෙරෝසිස් (Atherosclerosis)", "ඔස්ටියෝපොරෝසිස්", "ලෙප්ටොස්පයිරෝසිස්", "සිරෝසිස්", "කිරීටක ධමනි සම්පූර්ණයෙන් අවහිර වූ විට හෘද පේශියට ඔක්සිජන් නොලැබී හෘදයාබාධය (Heart Attack) ඇතිවේ."),
        q("මොළයට රුධිරය සපයන රුධිර නාලයක් අවහිර වීමෙන් හෝ පුපුරා යාමෙන් හදිසියේම ශරීරයේ එක් පැත්තක් අප්‍රාණික වීමේ රෝගය කුමක්ද?", "ආඝාතය හෙවත් අංශභාගය (Stroke)", "මීමැස්මොරය", "ඇදුම", "ගැස්ට්‍රයිටිස්", "මුහුණ ඇදවීම, අතක් පණ නැතිවීම හා කතාව ගොත ගැසීම (FAST ලක්ෂණ) ආඝාතයේ හදිසි අනතුරු ඇඟවීම් වේ."),
        q("බෝ නොවන රෝග වැළඳීමට බලපාන 'වෙනස් කළ හැකි අවදානම් සාධක' (Modifiable Risk Factors) මොනවාද?", "දුම්පානය, මත්පැන් භාවිතය, අහිතකර ආහාර රටාව සහ ශාරීරික ව්‍යායාම මඳකම", "වයස, ස්ත්‍රී පුරුෂ භාවය සහ ජානමය උරුමය", "උපන් දිනය සහ රුධිර ඝනය", "මව්පියන්ගේ උස", "පුද්ගලයෙකුගේ ජීවන රටාව වෙනස් කර ගැනීමෙන් බෝ නොවන රෝග 80%කට වඩා වළක්වා ගත හැක."),
        q("පුද්ගලයෙකුට තමාගේ උත්සාහයෙන් වෙනස් කළ නොහැකි බෝ නොවන රෝග අවදානම් සාධක (Non-modifiable Risk Factors) මොනවාද?", "වයස්ගත වීම, පවුලේ ප්‍රවේණිගත ඉතිහාසය සහ ස්ත්‍රී පුරුෂ භාවය", "ලුණු හා සීනි භාවිතය", "දුම්පානය", "ක්‍රියාශීලී නොවන ජීවිතය", "ජානමය අවදානමක් ඇති අය වයස අවුරුදු 35න් පසු නිතිපතා වෛද්‍ය පරීක්ෂණ කරවා ගැනීම වැදගත් වේ."),
        q("ශ්‍රී ලංකාවේ බෝ නොවන රෝග කල්තියා හඳුනාගැනීම සඳහා රජයේ රෝහල් හා MOH කාර්යාල ආශ්‍රිතව පිහිටුවා ඇති විශේෂ ඒකක මොනවාද?", "සුව දිවි මධ්‍යස්ථාන (Healthy Lifestyle Centres — HLCs)", "වෙළඳ මධ්‍යස්ථාන", "විනෝද උද්‍යාන", "පොලිස් මුරපොළවල්", "වයස අවුරුදු 35ට වැඩි සෑම පුරවැසියෙකුටම HLC මගින් නොමිලේ BMI, රුධිර පීඩනය සහ සීනි මට්ටම පරීක්ෂා කරගත හැක."),
        q("ශ්‍රී ලංකාවේ වියළි කලාපීය ගොවි ජනතාව අතර බහුලව වාර්තා වන නිදන්ගත වකුගඩු රෝගය (CKDu) පාලනය කිරීමට ගත යුතු ප්‍රධාන පියවර කුමක්ද?", "පිරිසිදු පෙරූ ජලය ප්‍රමාණවත් ලෙස පානය කිරීම සහ කෘෂි රසායන ආරක්ෂිතව අවම ලෙස භාවිත කිරීම", "ජලය පානය අඩු කිරීම", "වේදනා නාශක නිතර ගැනීම", "ලුණු පරිභෝජනය වැඩි කිරීම", "විජලනය, පානීය ජලයේ බැර ලෝහ හා කෘෂි රසායන අවිධිමත් භාවිතය CKDu රෝගයට දායක වන බව හඳුනාගෙන ඇත."),
        q("ශ්‍රී ලංකාවේ පිරිමි පුද්ගලයන් අතර බහුලව දක්නට ලැබෙන, බුලත්විට-දුම්කොළ හා දුම්පානය සමග සෘජුව බැඳුණු පිළිකා වර්ගය කුමක්ද?", "මුඛ පිළිකාව (Oral Cancer)", "අක්ෂි පිළිකාව", "චර්ම පිළිකාව", "අස්ථි පිළිකාව", "මුඛයේ සුව නොවන තුවාල, සුදු හෝ රතු පැල්ලම් (Leukoplakia) මුඛ පිළිකාවේ පූර්ව ලක්ෂණ විය හැක."),
        q("ශ්‍රී ලංකාවේ කාන්තාවන් අතර බහුලවම දක්නට ලැබෙන පිළිකා වර්ග දෙක මොනවාද?", "පියයුරු පිළිකා සහ ගැබ්ගෙල පිළිකා (Breast & Cervical Cancer)", "පෙනහලු හා වකුගඩු පිළිකා", "මොළයේ හා අස්ථි පිළිකා", "දිවේ හා සමේ පිළිකා", "ස්වයං පියයුරු පරීක්ෂාව සහ සුවනාරී සායනවලදී සිදුකරන පැප් පරීක්ෂණය (Pap Smear) මගින් මේවා කල්තියා හඳුනාගත හැක."),
        q("පිළිකාවක් කල්තියා හඳුනාගැනීමේ ජාත්‍යන්තර 'CAUTION' සංඥා අතරට අයත් වන ප්‍රධාන අනතුරු ඇඟවීමේ ලක්ෂණයක් කුමක්ද?", "සති 2-3කට වඩා කල් පවතින සුව නොවන තුවාලයක් හෝ කටහඬ ගොරෝසු වීමක්", "දිනක් ඇතුළත සුව වන සෙම්ප්‍රතිශ්‍යාව", "ව්‍යායාම කිරීමෙන් පසු දහඩිය දැමීම", "සාමාන්‍ය කුසගින්න දැනීම", "ශරීරයේ ඕනෑම තැනක අසාමාන්‍ය ගැටිත්තක්, රුධිර වහනයක් හෝ උපන් ලපයක වෙනසක් ඇති වුවහොත් වහාම වෛද්‍ය උපදෙස් පැතිය යුතුය."),
        q("ශ්වසන නාලිකා සංකෝචනය වී ශ්ලේෂ්මල පිරීම නිසා හුස්ම ගැනීමේදී සිහින් සීරුමාරු ශබ්දයක් (Wheezing) ඇතිවන නිදන්ගත රෝගය කුමක්ද?", "ඇදුම රෝගය (Bronchial Asthma)", "දියවැඩියාව", "සෙංගමාලය", "උණ සන්නිපාතය", "දූවිලි, දුම්, සීතල හා සමහර ආහාර අසාත්මිකතා නිසා ඇදුම රෝගය උත්සන්න විය හැක."),
        q("නිදන්ගත බාධාකාරී පෙනහලු රෝගය (COPD) ඇතිවීම සඳහා බලපාන ප්‍රධානතම පාරිසරික හා චර්යාත්මක හේතුව කුමක්ද?", "දුම්වැටි දුමාරය සහ ගෘහස්ථ දර ලිප් දුමට දිගුකාලීනව නිරාවරණය වීම", "පිරිසිදු ජලය බීම", "පලා වර්ග ආහාරයට ගැනීම", "උදෑසන ඇවිදීම", "වසර ගණනාවක් දුම් ආඝ්‍රාණය කිරීමෙන් පෙනහලු වායු මාර්ග ස්ථිරවම පටු වී හුස්ම ගැනීම අසීරු වේ."),
        q("සෞඛ්‍යාරක්ෂිත පානීය ජල ළිඳක් සහ ජල මුද්‍රිත වැසිකිළියක අපවිත්‍ර වළ (Soakage Pit) අතර තිබිය යුතු අවම ආරක්ෂිත දුර ප්‍රමාණය කොපමණද?", "අවම වශයෙන් මීටර් 15ක් (අඩි 50ක්) වත් දුරින් පිහිටිය යුතුය", "මීටර් 2ක්", "මීටර් 5ක්", "එක ළඟම තැබිය යුතුය", "වැසිකිළි වළේ අපවිත්‍ර ජලය භූගත ජල මට්ටම හරහා පානීය ළිඳට කාන්දු වීම වැළැක්වීමට මීටර් 15ක දුර අනිවාර්ය වේ."),
        q("සෞඛ්‍යාරක්ෂිත ජල ළිඳක ජලයට මතුපිට අපවිත්‍ර වැසි ජලය ගලා ඒම වැළැක්වීමට තිබිය යුතු භෞතික අංග මොනවාද?", "උස බැම්මක් (Parapet Wall), කොන්ක්‍රීට් ඇප්‍රනයක් සහ අපජලය ඉවත් කරන කාණුවක්", "විවෘත මඩ බිමක්", "ළිඳ අසල කසළ ගොඩක්", "වහලයක් පමණි", "නිවැරදි ලෙස ඉදිකළ කොන්ක්‍රීට් බැම්ම සහ ඇප්‍රනය ළිං ජලය අපවිත්‍ර වීමෙන් වළක්වයි."),
        q("පානීය ජලය ක්ෂුද්‍රජීවීන්ගෙන් තොර බවට තහවුරු කර ගැනීමට නිවසේදී කළ හැකි වඩාත්ම ආරක්ෂිත හා සරල ජල පිරිපහදු ක්‍රමය කුමක්ද?", "ජලය නටන තෙක් උණු කර විනාඩි කිහිපයක් තබා නිවාගෙන පානය කිරීම", "රෙදි කැබැල්ලකින් පෙරීම පමණි", "අව්වේ තැබීම පමණි", "සීනි මිශ්‍ර කිරීම", "සෙල්සියස් අංශක 100දී ජලය නටන විට බැක්ටීරියා, වෛරස් හා ප්‍රොටොසෝවා පරපෝෂිතයන් සම්පූර්ණයෙන්ම විනාශ වේ."),
        q("ගංවතුර වැනි ආපදා අවස්ථාවකදී පානීය ජලය විෂබීජහරණය කිරීම සඳහා බහුලව භාවිත කරන රසායනික ද්‍රව්‍යය කුමක්ද?", "ක්ලෝරීන් (Chlorine / ක්ලෝරීන් පෙති හෝ බ්ලීචින් ද්‍රාවණය)", "සල්ෆියුරික් අම්ලය", "භූමිතෙල්", "ලුණු කැට", "නියමිත මාත්‍රාවට ක්ලෝරීන් යෙදීමෙන් මහජන පානීය ජල සැපයුම් හා ළිං ජලය ආරක්ෂිත කළ හැක."),
        q("ඝන අපද්‍රව්‍ය කළමනාකරණයේදී භාවිත වන '3R' සංකල්පයෙන් අදහස් කරන පියවර තුන මොනවාද?", "අඩු කිරීම (Reduce), නැවත භාවිතය (Reuse) සහ ප්‍රතිචක්‍රීකරණය (Recycle)", "විකිණීම, පිළිස්සීම සහ වැළලීම", "එකතු කිරීම, විසි කිරීම සහ ගොඩගැසීම", "සේදීම, වියළීම සහ ගබඩා කිරීම", "අපද්‍රව්‍ය ජනනය අවම කර දිරාපත් වන කසළ කොම්පෝස්ට් කිරීම පරිසර සෞඛ්‍යයට ඉතා හිතකරය."),
        q("නිවසේ මුළුතැන්ගෙයින් ඉවතලන එළවළු හා පලතුරු කැබලි වැනි ජෛව හායනයට ලක්වන අපද්‍රව්‍ය කළමනාකරණය කිරීමේ හොඳම ක්‍රමය කුමක්ද?", "කාබනික පොහොර හෙවත් කොම්පෝස්ට් (Compost) නිෂ්පාදනය කර ගෙවතු වගාවට යොදාගැනීම", "ප්ලාස්ටික් මලුවල දමා පාර අයිනට දැමීම", "කාණුවලට දමා සිර කිරීම", "පොලිතින් සමග ගිනි තැබීම", "පොලිතින් හා ප්ලාස්ටික් ගිනි තැබීමෙන් පිළිකා කාරක ඩයොක්සින් වායුව නිකුත් වන බැවින් කසළ වෙන් කිරීම අත්‍යවශ්‍ය වේ."),
        q("ප්ලාස්ටික් සහ පොලිතින් වැනි නොදිරන අපද්‍රව්‍ය එළිමහනේ පිළිස්සීම නිසා පරිසරයට නිකුත් වන අතිශය විෂ සහිත පිළිකාකාරක වායුව කුමක්ද?", "ඩයොක්සින් සහ ෆියුරාන් (Dioxins & Furans)", "ඔක්සිජන්", "නයිට්‍රජන්", "ජල වාෂ්ප", "ප්ලාස්ටික් පිළිස්සීමේ දුම ආඝ්‍රාණයෙන් ශ්වසන රෝග, හෝමෝන ගැටලු සහ පිළිකා හටගනී."),
        q("සෞඛ්‍ය සම්පන්න පාසල් පරිසරයක් ගොඩනැගීමට ක්‍රියාත්මක වන 'සෞඛ්‍ය ප්‍රවර්ධන පාසල' (Health Promoting School) වැඩසටහනේ ප්‍රධාන අරමුණ කුමක්ද?", "පාසල් ප්‍රජාවේ කායික, මානසික හා සමාජීය සුවතාව ප්‍රවර්ධනය කරමින් ආරක්ෂිත ඉගෙනුම් පරිසරයක් නිර්මාණය කිරීම", "ක්‍රීඩා පිටිය කුඩා කිරීම", "ආපනශාලාවේ පැණි බීම පමණක් විකිණීම", "විභාග ප්‍රමාණය වැඩි කිරීම", "පිරිසිදු වැසිකිළි, ආරක්ෂිත පානීය ජලය, පෝෂ්‍යදායී ආපනශාලාව හා මනෝසමාජීය රැකවරණය මෙහි අංග වේ."),
        q("සත්ත්ව හා මානව මලපහ හා අපද්‍රව්‍ය විද්‍යාත්මකව බැහැර කිරීමට භාවිත කළ යුතු හොඳම වැසිකිළි ක්‍රමය කුමක්ද?", "ජල මුද්‍රිත වැසිකිළිය (Water-seal Latrine)", "වළ වැසිකිළිය පමණි", "එළිමහන් බැහැර කිරීම", "ගංගා ඉවුරු භාවිතය", "ජල මුද්‍රාව (Water-seal) මගින් දුගඳ පිටවීමත් මැස්සන් හා කැරපොත්තන් ඇතුළු වීමත් සම්පූර්ණයෙන්ම වළකාලයි."),
        q("ආහාර පිසීමේදී සහ පිළිගැන්වීමේදී රෝග කාරක බැක්ටීරියා වර්ධනය වන 'අන්තරායකාරී උෂ්ණත්ව කලාපය' (Temperature Danger Zone) කුමක්ද?", "සෙල්සියස් අංශක 5°C සිට 60°C දක්වා උෂ්ණත්ව පරාසය", "අංශක -20°C සිට 0°C දක්වා", "අංශක 80°C සිට 100°C දක්වා", "අංශක 120°C ට වැඩි", "පිසූ ආහාර පැය 2කට වඩා කාමර උෂ්ණත්වයේ තැබුවහොත් බැක්ටීරියා සීඝ්‍රයෙන් ගුණනය වී ආහාර විෂවීම සිදුවේ."),
        q("ආහාර විෂවීමක් (Food Poisoning) වැළඳුණු පුද්ගලයෙකු තුළ බොහෝ විට පැය කිහිපයක් ඇතුළත මතුවන මූලික රෝග ලක්ෂණ මොනවාද?", "වමනය, උදර කැක්කුම, ඔක්කාරය සහ දියරමය පාචනය", "සමේ සුදු ලප", "අස්ථි බිඳීම", "කන් ඇසීම නැතිවීම", "බැක්ටීරියා විෂ (Toxins) මිශ්‍ර වූ ආහාර ගැනීමෙන් මෙය හටගන්නා බැවින් පිරිසිදු උණුසුම් ආහාර ගැනීම වැදගත්ය."),
        q("ශ්‍රී ලංකාවේ ආයුර්වේද හා හෙළ වෙදකමේ පදනම වන 'ත්‍රිදෝෂ සිද්ධාන්තය'ට අයත් ප්‍රධාන දෝෂ තුන මොනවාද?", "වාත (Vata), පිත්ත (Pitta) සහ කඵ (Kapha)", "සීතල, උණුසුම සහ සුළඟ", "රක්ත, මාංශ සහ මේද", "පෘථිවි, ආපෝ සහ ආකාශ", "ත්‍රිදෝෂ සමතුලිතව පවතින විට නිරෝගී බවත්, ඒවා විෂම වූ විට රෝග හටගන්නා බවත් ආයුර්වේදයේ ඉගැන්වේ."),
        q("ආයුර්වේද වෛද්‍ය විද්‍යාවට අනුව මිනිස් සිරුර ඇතුළු විශ්වයේ සියලුම පදාර්ථ නිර්මාණය වී ඇති 'පංච මහා භූත' මොනවාද?", "පඨවි (පෘථිවි), ආපෝ (ජලය), තේජෝ (ගින්දර), වායෝ (වාතය) සහ ආකාශ (අවකාශය)", "රන්, රිදී, තඹ, යකඩ සහ ඊයම්", "වාත, පිත්ත, කඵ, රක්ත සහ මේද", "කාබන්, හයිඩ්‍රජන්, ඔක්සිජන්, නයිට්‍රජන් සහ කැල්සියම්", "ත්‍රිදෝෂ හා සප්ත ධාතු සියල්ලම මෙම පංච මහා භූතවල විවිධ සංයෝජනවලින් සැදී ඇත."),
        q("හෙළ වෙදකමේදී මානසික ඒකාග්‍රතාවය, මතක ශක්තිය සහ බුද්ධි වර්ධනය සඳහා අතීතයේ සිට බහුලව භාවිත කරන ඖෂධීය ශාකය කුමක්ද?", "ගොටුකොළ (Centella asiatica)", "කරපිංචා පමණි", "ඉඟුරු", "කොහොඹ පොතු", "ගොටුකොළ සම්බෝල, මැල්ලුම් හා කොළ කැඳ ලෙස ගැනීමෙන් මොළයේ ස්නායු ක්‍රියාකාරිත්වය උත්තේජනය වේ."),
        q("දියවැඩියා රෝගය පාලනය කිරීම සඳහා ශ්‍රී ලංකාවේ දේශීය වෙදකමේ ඉතා ප්‍රසිද්ධ හා විද්‍යාත්මකවද තහවුරු වී ඇති ඔසු ශාකය කුමක්ද?", "කොතලහිඹුටු (Salacia reticulata)", "වෙනිවැල්ගැට", "පාවට්ටා", "ඉරමුසු", "කොතලහිඹුටු මුල් තැම්බූ ජලය රුධිරයේ සීනි අවශෝෂණය පාලනය කිරීමට සමත් වන බව පර්යේෂණවලින්ද සනාථ වී ඇත."),
        q("වැල්පෙනෙල, ගොටුකොළ, හාතාවාරිය හා කරපිංචා වැනි ඖෂධීය පත්‍ර යොදා උදෑසනට පිළියෙළ කරන සාම්ප්‍රදායික ශ්‍රී ලාංකික පෝෂණීය ආහාරය කුමක්ද?", "කොළ කැඳ (Herbal Porridge / Kola Kenda)", "කිරි තේ", "පාන් සහ බටර්", "ක්ෂණික නූඩ්ල්ස්", "රතු කැකුළු හාල්, පොල්කිරි, සුදුලූණු, ඉඟුරු හා අමු කොළ යුෂ මිශ්‍ර කොළ කැඳ උදෑසන සම්පූර්ණ සමබල ආහාරයකි."),
        q("හෙළ වෙදකමේදී රුධිර කොලෙස්ටරෝල් මට්ටම අඩු කිරීමටත් අක්මාවේ සෞඛ්‍යය රැකීමටත් බෙහෙවින් උපකාරී වන කුළුබඩු ශාකය කුමක්ද?", "කරපිංචා (Murraya koenigii) සහ සුදුලූණු", "සීනි උණ", "විනාකිරි", "පාන්පිටි", "කරපිංචා හා සුදුලූණු ආහාරයට එක් කිරීමෙන් රුධිර නාලවල මේදය තැන්පත් වීම පාලනය වේ."),
        q("සෙම්ප්‍රතිශ්‍යාව, කැස්ස සහ ශ්වසන ආබාධ සුව කිරීම සඳහා දේශීය වෙදකමේ භාවිත කරන ප්‍රධාන පංච මූල හා ඔසු පානය කුමක්ද?", "ඉඟුරු, කොත්තමල්ලි, වෙනිවැල්ගැට සහ පාවට්ටා තැම්බූ පානය (පස්පංගුව)", "කෘත්‍රිම කෝලා බීම", "අයිස් වතුර", "කෝපි පමණි", "ඉඟුරු, කොත්තමල්ලි හා වෙනිවැල්ගැට ශරීරයේ ප්‍රතිශක්තිය වඩවා සෙම් ගතිය හා ඇඟපත වේදනාව සමනය කරයි."),
        q("හෙළ වෙදකමේදී ඇදුම සහ සෙම් කැස්ස සුව කිරීම සඳහා ප්‍රධාන වශයෙන් යොදාගන්නා ඖෂධීය පැළෑටිය කුමක්ද?", "පාවට්ටා හෙවත් ආඩතෝඩා (Adhatoda vasica)", "පොල්පලා", "නෙල්ලි", "හීන් බෝවිටියා", "පාවට්ටා කොළ හා මුල් ශ්වසන මාර්ගයේ සෙම ඉවත් කර පෙනහලු ක්‍රියාකාරිත්වය පහසු කරයි."),
        q("මූත්‍රා ගල්, මූත්‍රා දැවිල්ල සහ මූත්‍රා ආසාදන සුව කිරීම සඳහා දේශීය වෙදකමේ භාවිත කරන ඉතා ජනප්‍රිය ඖෂධීය ශාකය කුමක්ද?", "පොල්පලා (Aerva lanata) සහ රණවරා", "කරාබුනැටි", "ගම්මිරිස්", "සාදික්කා", "පොල්පලා තැම්බූ වතුර මූත්‍රා පද්ධතිය පිරිසිදු කර මූත්‍රා ගල් දිය කිරීමට උපකාරී වේ."),
        q("හෙළ වෙදකමේදී අක්මා රෝග සහ සෙංගමාලය (Jaundice) සඳහා විශිෂ්ට ප්‍රතිකාරයක් ලෙස භාවිත කරන ශාක මොනවාද?", "හීන් බෝවිටියා (Osbeckia octandra) සහ පිටවක්කා", "කොත්තමල්ලි", "බෙලිමල්", "වැල්මී", "හීන් බෝවිටියා අක්මා සෛල ආරක්ෂා කර අක්මාවේ එන්සයිම සමතුලිත කිරීමට ඉතා ගුණදායක බව තහවුරු වී ඇත."),
        q("බැක්ටීරියා නාශක (Antibacterial) හා ප්‍රදාහ නාශක (Anti-inflammatory) ගුණයෙන් පොහොසත් ස්වාභාවික විෂබීජ නාශකයක් ලෙස දේශීය වෙදකමේ යොදාගන්නා ඔසුව කුමක්ද?", "කහ (Turmeric — Curcuma longa) සහ කොහොඹ (Neem)", "ලුණු පමණි", "සීනි", "පොල්තෙල් පමණි", "කහ වල අඩංගු කර්කියුමින් (Curcumin) සංයෝගය ප්‍රබල ප්‍රතිඔක්සිකාරකයක් හා විෂබීජ නාශකයකි."),
        q("ආයුර්වේදයේදී 'දිනචර්යාව' (Dinacharya) යන සංකල්පයෙන් උගන්වනු ලබන්නේ කුමක්ද?", "නිරෝගී දිවියක් සඳහා අලුයම අවදි වීමේ සිට රාත්‍රී නින්ද දක්වා අනුගමනය කළ යුතු විධිමත් දෛනික සෞඛ්‍ය චර්යාවන්ය", "වසරකට වරක් ගන්නා ආහාර", "රෝගී වූ පසු ගන්නා බෙහෙත් පමණි", "සෘතු වෙනස්වීම් පමණි", "වේලාසන අවදි වීම, දත් මැදීම, අභ්‍යංග (තෙල් ගැල්වීම), ව්‍යායාම හා නියමිත වේලාවට ආහාර ගැනීම දිනචර්යාවට අයත් වේ."),
        q("ආයුර්වේද වෛද්‍ය ක්‍රමයේදී වසරේ සෘතු හා කාලගුණ වෙනස්වීම් අනුව ආහාර හා ජීවන රටාව සකස් කර ගැනීම හඳුන්වන්නේ කෙසේද?", "සෘතුචර්යාව (Ritucharya)", "දිනචර්යාව", "පංචකර්මය", "ත්‍රිදෝෂය", "උණුසුම් ග්‍රීෂ්ම සෘතුවේදී සිසිල් ආහාරද වැසි හා සීතල සමයේදී උණුසුම් ආහාරද ගැනීම රෝග වළකාලයි."),
        q("නිතර ඇතිවන මලබද්ධය, ආහාර අරුචිය හා ශරීරය සිසිල් කර ගැනීම සඳහා හෙළ වෙදකමේදී සකසන ඖෂධීය බීම වර්ග මොනවාද?", "බෙලිමල්, රණවරා, ඉරමුසු සහ නෙල්ලි තැම්බූ පාන", "කෘත්‍රිම රසකාරක පැණි බීම", "අධික ශක්තිජනක බීම", "මත්පැන්", "සීනි අඩු ස්වාභාවික ඖෂධීය පාන ශරීරය විජලනයෙන් මුදා ප්‍රතිඔක්සිකාරක සපයයි."),
        q("දේශීය හෙළ වෙදකමේ අස්ථි බිඳීම්, විසන්ධි වීම් හා තැලීම් සඳහා ප්‍රතිකාර කරන සුවිශේෂී සම්ප්‍රදායික වෛද්‍ය ක්ෂේත්‍රය කුමක්ද?", "කැඩුම් බිඳුම් වෙදකම (Traditional Orthopaedics)", "විෂ වෙදකම", "අක්ෂි වෙදකම", "චර්ම වෙදකම", "පත්තු බැඳීම, තැවිලි හා ඖෂධීය තෙල් ගැල්වීම මගින් අස්ථි හා සන්ධි සුවපත් කිරීම ශ්‍රී ලංකාවේ පැරණි කලාවකි."),
        q("ශ්‍රී ලංකාවේ සර්ප දෂ්ටන වැනි හදිසි විෂ ශරීරගත වීම්වලට ප්‍රතිකාර කළ සාම්ප්‍රදායික හෙළ වෙද ක්ෂේත්‍රය කුමක්ද?", "විෂ වෙදකම (Traditional Toxicology — සර්ප විෂ වෙදකම)", "කැඩුම් බිඳුම් වෙදකම", "බාල රෝග වෙදකම", "නාඩි වෙදකම", "කෙසේ වෙතත් නූතන යුගයේදී ඕනෑම විෂ සර්ප දෂ්ටනයකදී වහාම රජයේ රෝහලකට ගෙන ගොස් Anti-venom ප්‍රතිකාරය ලබාදිය යුතුය."),
        q("ප්‍රජාව තුළ රෝග නිවාරණය හා සෞඛ්‍ය සංරක්ෂණය සඳහා සාම්ප්‍රදායික හෙළ වෙදකම සහ බටහිර වෛද්‍ය විද්‍යාව සම්බන්ධයෙන් පැවතිය යුතු නිවැරදි ආකල්පය කුමක්ද?", "රෝග නිවාරණයට හා සුවතාවයට දේශීය සෞඛ්‍ය පුරුදු අගය කරමින් හදිසි හා බරපතළ රෝගවලදී විද්‍යාත්මක වෛද්‍ය ප්‍රතිකාර ප්‍රමාද නොකර ලබාගැනීම", "බටහිර වෛද්‍ය විද්‍යාව සම්පූර්ණයෙන් ප්‍රතික්ෂේප කිරීම", "දේශීය ඔසු ශාක සියල්ල විනාශ කිරීම", "වෛද්‍ය උපදෙස් නොමැතිව ඖෂධ දෙවර්ගයම මිශ්‍ර කර ගැනීම", "සාම්ප්‍රදායික පෝෂණ හා ජීවන පුරුදු රෝග නිවාරණයට අගනා පිටිවහලක් වන අතර නූතන වෛද්‍ය විද්‍යාව ජීවිත බේරා ගනී."),
        q("සෑම පුරවැසියෙකුම සෞඛ්‍යාරක්ෂිත ප්‍රජාවක් ගොඩනැගීම සඳහා තම නිවසේ හා ගෙවත්තේ කළ යුතු ඉතා සරල හා ඵලදායී සේවාව කුමක්ද?", "මදුරුවන් බෝවන තැන් විනාශ කර, අපද්‍රව්‍ය වර්ගීකරණය කර, ස්වාභාවික එළවළු හා ඔසු පැළ සිටුවීම", "කසළ පාරට දැමීම", "රසායනික පොහොර අධිකව යෙදීම", "ජලය අපතේ යැවීම", "නිරෝගී ප්‍රජාවක් ආරම්භ වන්නේ පිරිසිදු හා පරිසර හිතකාමී නිවසකින් හා පවුලකිනි."),
        q("පළමු වර්ගයේ දියවැඩියාව (Type 1 Diabetes) ඇතිවීමට මූලික හේතුව කුමක්ද?", "අග්න්‍යාශයේ බීටා සෛල විනාශ වී ශරීරයේ ඉන්සියුලින් හෝමෝනය කිසිසේත්ම නිපදවීමට නොහැකි වීම", "විටමින් A අඩුවීම", "අධික ජලය පානය", "කැල්සියම් හිඟකම", "බොහෝ විට කුඩා හා තරුණ වියේදී මතුවන Type 1 දියවැඩියාවට දිනපතා ඉන්සියුලින් එන්නත් ලබාදීම අත්‍යවශ්‍ය වේ."),
        q("දියවැඩියා රෝගියෙකුගේ පාදවල තුවාල ඇතිවී ඒවා ඔඩු දුවා කපා ඉවත් කිරීමේ අවදානම වැළැක්වීමට ගත යුතු නිවැරදි පියවර කුමක්ද?", "දිනපතා පාද පරීක්ෂා කර සෝදා වියළිව තබාගැනීම, පාවහන් නොමැතිව නොඇවිදීම සහ මෘදු සපත්තු පැළඳීම", "තද සපත්තු පැළඳීම", "රළු මතුපිට පාවහන් නැතිව ඇවිදීම", "තුවාල මත තෙල් තවරා වසා තැබීම", "දියවැඩියාවේදී පාදයේ ස්නායු සංවේදනය අඩු වන බැවින් (Neuropathy) කුඩා තුවාලයක් පවා නොදැනී උග්‍ර විය හැක."),
        q("රුධිර පීඩනය මැනීමේදී 120/80 mmHg ලෙස සටහන් කරන විට ඉහළ අගය (120) මගින් නිරූපණය කරන්නේ කුමක්ද?", "හෘද කෝෂිකා සංකෝචනය වන විට ධමනි බිත්ති මත ඇතිවන උපරිම සිස්ටොලික් පීඩනය (Systolic BP)", "හෘදය විවේක ගන්නා විට ඇතිවන අවම පීඩනය", "පෙනහලු පීඩනය", "ශිරා තුළ පීඩනය", "හෘදය ලිහිල් වන අවස්ථාවේ ඇතිවන පහළ අගය ඩයස්ටොලික් පීඩනය (Diastolic BP) ලෙස හැඳින්වේ."),
        q("අධි රුධිර පීඩනය හා කොලෙස්ටරෝල් පාලනය කර ගනිමින් හෘද රෝගවලින් වැළකීමට WHO නිර්දේශ කරන දෛනික ශාරීරික ක්‍රියාකාරකම් ප්‍රමාණය කුමක්ද?", "දිනකට අවම වශයෙන් විනාඩි 30ක්වත් මධ්‍යම ප්‍රමාණයේ ව්‍යායාමයක (උදා වේගයෙන් ඇවිදීම) නිරත වීම", "මසකට වරක් විනාඩි 10ක් ඇවිදීම", "පැය 10ක් එක දිගට වාඩි වී සිටීම", "ව්‍යායාම සම්පූර්ණයෙන් නතර කිරීම", "නිතිපතා ස්වායු ව්‍යායාම කිරීමෙන් හිතකර HDL කොලෙස්ටරෝල් වැඩි වී රුධිර නාල නම්‍යශීලී වේ."),
        q("කිරීටක ධමනි අර්ධ වශයෙන් පටු වීම නිසා වෙහෙසෙන විට හදවතට ප්‍රමාණවත් ඔක්සිජන් නොලැබී පපුව මැද ඇතිවන තද වීමේ වේදනාව කුමක්ද?", "ඇන්ජයිනා (Angina Pectoris)", "ඇදුම", "ගැස්ට්‍රයිටිස්", "සිරෝසිස්", "ඇන්ජයිනා වේදනාව වම් අතට, බෙල්ලට හෝ හකු ප්‍රදේශයට පැතිර යා හැකි අතර විවේක ගැනීමෙන් හා ඖෂධවලින් සමනය වේ."),
        q("පාසල් වියේ දරුවන්ට නිසි ප්‍රතිකාර නොලැබෙන ස්ට්‍රෙප්ටොකොකස් උගුරේ ආසාදන නිසා පසුකාලීනව හෘද කපාටවලට හානි කරන රෝගය කුමක්ද?", "රූමැටික් හෘද රෝගය (Rheumatic Heart Disease — RHD)", "සරම්ප", "තැලසීමියාව", "පෝලියෝ", "උගුරේ අමාරුව හා හන්දි ඉදිමීම (Rheumatic Fever) සඳහා නියමිත ප්‍රතිජීවක අඛණ්ඩව ගැනීමෙන් හෘද කපාට හානිය වළකාලයි."),
        q("බෝ නොවන රෝග අවදානම පෙන්නුම් කරන 'මධ්‍යගත ස්ථූලතාව' (Central Obesity) මැන බැලීමට BMI වලට අමතරව භාවිත කරන සරල මිනුම කුමක්ද?", "ඉණ වටප්‍රමාණය (Waist Circumference) මැනීම", "හිස වටප්‍රමාණය මැනීම", "පාදයේ දිග මැනීම", "නියපොතු දිග මැනීම", "උදරය වටා තැන්පත් වන මේදය (Visceral Fat) දියවැඩියාව හා හෘද රෝග සඳහා ඉතා ප්‍රබල අවදානම් සාධකයකි."),
        q("වැඩිහිටි වියේදී අස්ථිවල ඛනිජ ඝනත්වය අඩු වී සුළු වැටීමකින් පවා අස්ථි පහසුවෙන් බිඳී යාමේ නිදන්ගත රෝගය කුමක්ද?", "ඔස්ටියෝපොරෝසිස් (Osteoporosis)", "ඇතරොස්ක්ලෙරෝසිස්", "රිකට්ස්", "ආතරයිටිස්", "තරුණ වියේ සිට කැල්සියම්, විටමින් D සහ බර උසුලන ව්‍යායාමවල යෙදීමෙන් මහලු වියේ ඔස්ටියෝපොරෝසිස් වළක්වා ගත හැක."),
        q("සන්ධිවල කාටිලේජ ගෙවී යාම හෝ ප්‍රදාහය නිසා සන්ධි ඉදිමී වේදනාව ඇතිවන රෝග තත්ත්වය හඳුන්වන්නේ කෙසේද?", "සන්ධි ප්‍රදාහය හෙවත් ආතරයිටිස් (Arthritis)", "ඇන්ජයිනා", "එම්ෆයිසීමා", "ඇනොරෙක්සියා", "ප්‍රශස්ත ශරීර බර පවත්වා ගැනීම හා නිවැරදි ඉරියව් අනුගමනය කිරීම දණහිස් සන්ධි ආතරයිටිස් අවම කරයි."),
        q("හිරු එළියේ ඇති අධික පාරජම්බුල කිරණවලට (UV Rays) දිගුකාලීනව නිරාවරණය වීම නිසා ඇතිවිය හැකි බෝ නොවන රෝග මොනවාද?", "සමේ පිළිකා (Skin Cancer) සහ ඇසේ සුද ඇතිවීම (Cataracts)", "මැලේරියාව", "කොළරාව", "දත් දිරාපත් වීම", "අධික මධ්‍යහ්න අව් රශ්මියෙන් ආරක්ෂා වීමට තොප්පි, කුඩ හා UV ආරක්ෂිත අව් කණ්ණාඩි භාවිතය උපකාරී වේ."),
        q("අධික සීනි, ලුණු හා අහිතකර ට්‍රාන්ස් මේදය (Trans Fats) අඩංගු අධි-සැකසූ ආහාර පැකට් හඳුනාගැනීමට ශ්‍රී ලංකාවේ ක්‍රියාත්මක වන වර්ණ සංකේත ක්‍රමය කුමක්ද?", "රථවාහන සංඥා වර්ණ කේත ක්‍රමය (Traffic Light Labelling — රතු, කහ, කොළ)", "තරු ශ්‍රේණිගත කිරීම", "අකුරු පමණි", "රූප සටහන් පමණි", "රතු ලකුණ පෙන්නුම් කරන්නේ එම ආහාරයේ සීනි, ලුණු හෝ මේදය ඉතා අධික බවයි — කොළ ලකුණ සෞඛ්‍යාරක්ෂිත මට්ටම පෙන්වයි."),
        q("නාගරික හා කාර්මික ප්‍රදේශවල වායු දූෂණයෙන් පෙනහලුවලට ගැඹුරින් ඇතුළු වී හෘද හා ශ්වසන රෝග ඇති කරන අතිශය කුඩා අංශු මොනවාද?", "සියුම් අංශුමය ද්‍රව්‍ය (PM2.5 සහ PM10)", "ඔක්සිජන් අණු", "ජල බිඳිති පමණි", "හීලියම් වායුව", "වාහන දුම් හා කර්මාන්තශාලා දුම්වල ඇති PM2.5 අංශු රුධිර සංසරණයට පවා ඇතුළු වීමට තරම් කුඩාය."),
        q("ඉවතලන පැරණි ජංගම දුරකථන, පරිගණක හා CFL බල්බ වැනි විද්‍යුත් අපද්‍රව්‍ය (E-waste) සාමාන්‍ය කසළ සමග බැහැර නොකළ යුත්තේ මන්ද?", "ඒවායේ ඇති ඊයම් (Lead), රසදිය (Mercury) සහ කැඩ්මියම් වැනි බැර ලෝහ පසට හා ජලයට මුසු වී ස්නායු හා වකුගඩු විනාශ කරන බැවින්", "ඒවා ඉක්මනින් දිරාපත් වන නිසා", "මදුරුවන් බෝවන නිසා පමණි", "දුගඳ හමන නිසා", "විද්‍යුත් අපද්‍රව්‍ය විධිමත් E-waste එකතු කිරීමේ මධ්‍යස්ථාන වෙත පමණක් භාර දිය යුතුය."),
        q("රෝහල් හා සායනවලින් ඉවතලන රුධිරය තැවරුණු පුළුන්, වෙළුම් පටි හා ආසාදිත සායනික අපද්‍රව්‍ය වෙන් කර දැමිය යුතු වර්ණ බෑගය කුමක්ද?", "කහ පැහැති බෑගය (Yellow Bag — සායනික ආසාදිත අපද්‍රව්‍ය)", "කොළ පැහැති බෑගය", "නිල් පැහැති බෑගය", "සුදු පැහැති බෑගය", "සායනික අපද්‍රව්‍ය වෙන් කර විද්‍යාත්මකව දහනය කිරීමෙන් රෝහල් ආශ්‍රිත බෝවන රෝග පැතිරීම වැළකේ."),
        q("ආයුර්වේදයට අනුව ආහාර නිසි ලෙස ජීර්ණය කර සිරුරේ පෝෂ්‍ය කොටස් බවට පත් කරන අභ්‍යන්තර ජීර්ණ ශක්තිය හඳුන්වන්නේ කෙසේද?", "අග්නි (ජඨරාග්නි / Digestive Fire)", "ආම", "සප්ත ධාතු", "මල", "ජඨරාග්නිය නිසි ලෙස ක්‍රියාත්මක නොවූ විට ආහාර හරිහැටි නොපැසී සිරුර තුළ 'ආම' නම් විෂ හටගන්නා බව ඉගැන්වේ."),
        q("ආයුර්වේදයේදී සප්ත ධාතු (ශරීරයේ මූලික පටක 7) ලෙස හඳුන්වන සංඝටක අතර පළමුවැන්න සහ පදනම වන්නේ කුමක්ද?", "රස ධාතුව (ආහාරයෙන් සැදෙන මූලික පෝෂණ තරලය)", "අස්ථි ධාතුව", "ශුක්‍ර ධාතුව", "මේද ධාතුව", "රස, රක්ත, මාංශ, මේද, අස්ථි, මජ්ජා සහ ශුක්‍ර යන පිළිවෙළින් සප්ත ධාතු පෝෂණය වේ."),
        q("ආයුර්වේදයේදී ශරීරයේ ත්‍රිදෝෂ අතුරින් චලනය, ස්නායු ආවේග, හුස්ම ගැනීම හා බහිස්ස්‍රාවී ක්‍රියා පාලනය කරන ප්‍රධාන දෝෂය කුමක්ද?", "වාත දෝෂය (Vata)", "පිත්ත දෝෂය", "කඵ දෝෂය", "රක්ත දෝෂය", "වාත දෝෂය කුපිත වූ විට හන්දි වේදනා, බඩ පිපුම, මලබද්ධය හා නින්ද නොයාම ඇතිවන බව ආයුර්වේදය දක්වයි."),
        q("ආයුර්වේදයට අනුව ආහාර ජීර්ණය, ශරීර උෂ්ණත්වය, පෙනීම සහ පරිවෘත්තීය ක්‍රියාවලීන් පාලනය කරන දෝෂය කුමක්ද?", "පිත්ත දෝෂය (Pitta)", "වාත දෝෂය", "කඵ දෝෂය", "ආකාශ භූතය", "පිත්ත දෝෂය අධික වූ විට ඇසිඩිටි (අම්ලපිත්ත රෝගය), සමේ දැවිල්ල හා අධික කෝපය ඇතිවේ."),
        q("ශරීරයට ශක්තිය, සන්ධිවල ලිහිසි බව, ස්ථාවරත්වය සහ ප්‍රතිශක්තිය ලබාදෙන ආයුර්වේදීය දෝෂය කුමක්ද?", "කඵ දෝෂය (Kapha)", "වාත දෝෂය", "පිත්ත දෝෂය", "මල කොටස", "කඵ දෝෂය අසමතුලිතව වැඩි වූ විට සෙම්ප්‍රතිශ්‍යාව, පීනස, ඇදුම හා සිරුරේ අධික බර ගතිය හටගනී."),
        q("ආයුර්වේද වෛද්‍ය ක්‍රමයේදී ශරීරයේ ඇති දූෂිත දෝෂ මුළුමනින්ම ඉවත් කර ශරීරය පවිත්‍ර කරන ප්‍රධාන විෂහරණ ප්‍රතිකාර පද්ධතිය කුමක්ද?", "පංචකර්ම ප්‍රතිකාරය (Panchakarma)", "නාඩි පරීක්ෂාව", "දිනචර්යාව", "ඔසු උයන", "වමන, විරේචන, වස්ති, නස්‍ය හා රක්තමෝක්ෂණ යන ප්‍රතිකාර පහ පංචකර්මයට අයත් වේ."),
        q("හෙළ වෙදකමේදී පීනස, හිසරදය හා සෙම් අමාරු සුව කිරීම සඳහා නාසයට ඖෂධීය තෙල් හෝ යුෂ බිංදු දැමීමේ ප්‍රතිකාර ක්‍රමය කුමක්ද?", "නස්‍ය කර්මය (Nasya Karma)", "වමන කර්මය", "විරේචන කර්මය", "වස්ති කර්මය", "නස්‍ය කර්මය මගින් ශීර්ෂ ප්‍රදේශයේ සිරවී ඇති සෙම ඉවත් වී ස්වසන මාර්ග පිරිසිදු වේ."),
        q("සෙම්ප්‍රතිශ්‍යාව, හිස බර ගතිය හා නාසය සිරවීමේදී දේශීය වෙදකමේදී භාවිත කරන ඖෂධීය කොළ තැම්බූ ජලයේ හුමාලය ඇල්ලීමේදී බහුලව යොදාගන්නා ශාක මොනවාද?", "නික, පාවට්ටා, යක්වනැස්ස, දෙහි කොළ හා කහ", "කැරට් හා බීට්රූට්", "රතු අල", "තේ කොළ පමණි", "ඖෂධීය වාෂ්ප ආඝ්‍රාණයෙන් නාසිකා හා ශ්වාසනාල පටක ලිහිල් වී හුස්ම ගැනීම පහසු කරයි."),
        q("ශ්‍රී ලංකාවේ ළමුන්ගේ කුසගින්න අඩු වීම, පණු අමාරු හා කැස්ස සඳහා දේශීය වෙදකමේ බහුලව යොදාගන්නා ඖෂධීය කුළුබඩු ශාකය කුමක්ද?", "තිප්පිලි (Piper longum) සහ ඉඟුරු", "විනාකිරි", "සෝඩියම් ක්ලෝරයිඩ්", "රසදිය", "තිප්පිලි, ඉඟුරු හා ගම්මිරිස් එක්ව ගත් කල ආයුර්වේදයේ 'ත්‍රිකටු' ලෙස හඳුන්වන අතර ජීර්ණ ශක්තිය වඩවයි."),
        q("උගුරේ වේදනාව, කටහඬ ගොරෝසු වීම හා වියළි කැස්ස සුව කිරීම සඳහා ආයුර්වේදයේ හා හෙළ වෙදකමේ බෙහෙවින්ම ගුණදායක ලෙස භාවිත කරන ඖෂධය කුමක්ද?", "වැල්මී (Licorice — Glycyrrhiza glabra)", "මිරිස් කරල්", "සියඹලා ඇට", "පුවක්", "වැල්මී උගුරේ ශ්ලේෂ්මල පටල සිසිල් කර ප්‍රදාහය අඩු කිරීමේ ස්වාභාවික ගුණයෙන් යුක්තය."),
        q("පාසල් දරුවන්ගේ නින්ද නොයාම, ශාරීරික වෙහෙස හා අධික පිපාසය සමනය කිරීමටත් පෝෂණයටත් හෙළ වෙදකමේ නිර්දේශ කරන මුල් හා අල වර්ගය කුමක්ද?", "හාතාවාරිය (Asparagus racemosus) සහ ඉරමුසු (Hemidesmus indicus)", "මඤ්ඤොක්කා පොතු", "කොස් ඇට පමණි", "කිතුල් හකුරු පමණි", "හාතාවාරිය කැඳ මෙන්ම ඉරමුසු පානය සිරුරේ විෂ ද්‍රව්‍ය ඉවත් කර ශක්තිය වඩවයි."),
        q("සමේ තුවාල, දද, කුෂ්ඨ හා කුරුලෑ සුව කිරීමට ස්වාභාවික විෂබීජ නාශකයක් ලෙස දේශීය වෙදකමේ අනාදිමත් කාලයක සිට භාවිත කරන වෘක්ෂය කුමක්ද?", "කොහොඹ (Azadirachta indica)", "තේක්ක", "පයිනස්", "රබර්", "කොහොඹ කොළ තැම්බූ ජලයෙන් සේදීම සහ කොහොඹ තෙල් ගැල්වීම චර්ම රෝග රැසකට ප්‍රත්‍යක්ෂ ප්‍රතිකාරයකි."),
        q("ශ්‍රී ලංකාවේ බහුලව වැවෙන, කැස්ස හා ඇදුම රෝගීන්ගේ සෙම ඉවත් කිරීමට විශිෂ්ට ඖෂධයක් ලෙස ගම්බද ජනතාව යොදාගන්නා පැළෑටිය කුමක්ද?", "කුප්පමේනියා (Acalypha indica)", "තණකොළ", "නිදිකුම්බා", "හබරල", "කුප්පමේනියා කොළ මැල්ලුම හෝ යුෂ ශ්වසන මාර්ගයේ ශ්ලේෂ්මල පිරිසිදු කිරීමට උපකාරී වේ."),
        q("ප්‍රතිශක්තිය වැඩි කිරීමටත් විටමින් C බහුල ස්වාභාවික ප්‍රතිඔක්සිකාරකයක් ලෙසත් ආයුර්වේදයේ 'ත්‍රිඵලා' ඖෂධයට අයත් වන පළතුරු වර්ග තුන මොනවාද?", "අරළු, බුළු සහ නෙල්ලි", "අඹ, කෙසෙල් සහ පැපොල්", "දෙළුම්, මිදි සහ ඇපල්", "කොස්, දෙල් සහ අලිගැටපේර", "අරළු, බුළු, නෙල්ලි (ත්‍රිඵලා) ආහාර ජීර්ණය ක්‍රමවත් කර රෝග ප්‍රතිරෝධීතාව ඉහළ නංවන රසායන ඖෂධයකි."),
        q("උණ, බඩගින්න නැති වීම සහ ආහාර ජීර්ණ අපහසුතා ඇති විට හෙළ වෙදකමේදී සකසා දෙන කුළුබඩු මිශ්‍ර සුප් පානය කුමක්ද?", "තැම්බුම් හොද්ද (Thambum Hodda)", "කිරි තේ", "පැණි බීම", "සුප් කැට පානය", "ගම්මිරිස්, සුදුලූණු, කොත්තමල්ලි, උළුහාල්, කරපිංචා හා සියඹලා මිශ්‍ර තැම්බුම් හොද්ද ජඨරාග්නිය උත්තේජනය කරයි."),
        q("කැඩුම් බිඳුම් වෙදකමේදී තැළුණු හෝ ඉදිමුණු ස්ථානවල වේදනාව හා ඉදිමුම අඩු කිරීමට යොදන ඖෂධීය පැළෑටි මොනවාද?", "කැටකෑල, මානෙල්, පාවට්ටා හා රත්මල් කොළ තැවිලි සහ පත්තු", "සීනි හා පිටි", "ලුණු කැට පමණි", "අයිස්ක්‍රීම්", "කැඩුම් බිඳුම් වෙදකමේදී උණුසුම් තැවිලි මගින් රුධිර සංසරණය වැඩි කර පටක සුවවීම වේගවත් කෙරේ."),
        q("හදිසි හෘදයාබාධයක්, දරුණු හදිසි අනතුරක් හෝ අධික රුධිර වහනයක් ඇති වූ විට ගත යුතු නිවැරදි ක්‍රියාමාර්ගය කුමක්ද?", "කල් නොදමා වහාම 1990 සුවසැරිය ගිලන්රථ සේවාව හෝ බටහිර වෛද්‍ය රෝහලක හදිසි ප්‍රතිකාර ඒකකය වෙත යොමු කිරීම", "නිවසේ කෂායක් පමණක් තම්බා දීම", "දින 3ක් බලා සිටීම", "රෝගියාට ඇවිදීමට සැලැස්වීම", "හදිසි මාරාන්තික අවස්ථාවලදී 'රන් පැය' (Golden Hour) තුළ නවීන හදිසි වෛද්‍ය ප්‍රතිකාර ලබාදීමෙන් ජීවිත බේරේ."),
        q("දේශීය හෙළ වෙදකමේදී රෝගියෙකුගේ ශරීර ස්වභාවය සහ දෝෂ තත්ත්වය හඳුනාගැනීමට වෙද මහතා විසින් සිදුකරන සාම්ප්‍රදායික පරීක්ෂණ ක්‍රමය කුමක්ද?", "නාඩි පරීක්ෂාව (මැණික් කටුව අසල ධමනි ස්පන්දනය පරීක්ෂා කිරීම)", "X-රේ පරීක්ෂණය", "CT ස්කෑන් පරීක්ෂණය", "ECG පරීක්ෂණය", "වාත, පිත්ත හා කඵ නාඩිවල ගමන් රටාව අනුව අභ්‍යන්තර රෝග තත්ත්වයන් හඳුනාගැනීමට දේශීය වෙදැදුරෝ සමත් වූහ."),
        q("ප්‍රජා සෞඛ්‍යය රැකගැනීම සඳහා පාසල තුළ 'ඔසු උයනක්' (School Herbal Garden) පවත්වාගෙන යාමෙන් සිසුන්ට ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "වඳ වී යන දේශීය ඖෂධීය ශාක හඳුනාගෙන සංරක්ෂණය කිරීමටත් ඒවායේ සෞඛ්‍ය ගුණ ප්‍රායෝගිකව ඉගෙනීමටත් හැකිවීම", "පාඩම් කාලය මගහැරීමට", "ක්‍රීඩා පිටිය කුඩා කිරීමට", "අලංකාර මල් පමණක් වැවීමට", "දේශීය ඔසු ශාක හඳුනාගැනීම අපේ සාම්ප්‍රදායික සෞඛ්‍ය උරුමය අනාගත පරපුරට රැකදීමකි."),
        q("උදරයේ අධික දැවිල්ල (Gastritis / අම්ලපිත්ත රෝගය) සහ මූත්‍රා අමාරු සමනය කිරීමට ඉතා ගුණදායක දේශීය ඔසු ශාකයක් වන්නේ කුමක්ද?", "නීරමුල්ලිය (Hygrophila schulli) හා කෝමාරිකා (Aloe vera)", "ගම්මිරිස්", "අබ", "විනාකිරි", "නියමිත වේලාවට ආහාර ගැනීමත් අධික මිරිස් තෙල් පාලනයත් සමග කෝමාරිකා වැනි සිසිල් ආහාර ගැස්ට්‍රයිටිස් සමනය කරයි."),
        q("අභ්‍යන්තර රුධිර සංසරණය ක්‍රමවත් කර මාංශ පේශි විඩාව දුරු කිරීමට ආයුර්වේද දිනචර්යාවේදී නිර්දේශ කරන දෛනික හෝ සතිපතා ක්‍රියාව කුමක්ද?", "අභ්‍යංග හෙවත් ස්වාභාවික ඖෂධීය තෙල් සිරුරේ ගල්වා සම්බාහනය කිරීම", "දිනපතා නිරාහාරව සිටීම", "උණු අළු තැවීම", "ව්‍යායාම නොකර සිටීම", "අභ්‍යංග මගින් සමේ තෙතමනය රැකෙන අතර සන්ධි හා ස්නායු පද්ධතිය ශක්තිමත් වේ."),
        q("දේශීය වෙදකමේදී මලබද්ධය වැළැක්වීමටත් අග්නි දීප්තිය ඇති කිරීමටත් ඉතා ගුණදායක පළතුරක් ලෙස හඳුන්වන 'ගස් බෙලි' හෙවත් බෙලි (Bael Fruit) ගෙඩියේ ඇති විශේෂ ගුණය කුමක්ද?", "ආමාශයේ හා බඩවැලේ ශ්ලේෂ්මල පටල ආරක්ෂා කර අතීසාරය හා මලබද්ධය යන දෙකම සමබර කිරීම", "රුධිර පීඩනය වැඩි කිරීම", "නින්ද නැති කිරීම", "සෙම වැඩි කිරීම", "තන්තු බහුල බෙලි පලතුර හා බෙලිමල් පානය ශ්‍රී ලාංකිකයන්ගේ ජීර්ණ පද්ධතියේ මිතුරෙකි."),
        q("දියවැඩියාව හා අධික කොලෙස්ටරෝල් ඇති රෝගීන්ට පමණක් නොව සාමාන්‍ය ජනතාවටද හෙළ වෙදකම නිර්දේශ කරන බත් පිළියෙළ කිරීමේ ක්‍රමය කුමක්ද?", "කුරුට්ට සහිත දේශීය පාරම්පරික රතු හෝ සුදු සහල් (උදා සුවඳැල්, කුරුළුතුඩ, කළු හීනැටි) ආහාරයට ගැනීම", "අධික ලෙස පොලිෂ් කළ සුදු සහල් පමණක් කෑම", "පාන්පිටි ආහාර පමණක් ගැනීම", "සීනි මිශ්‍ර බත් කෑම", "පාරම්පරික සහල්වල අඩු ග්ලයිසමික් දර්ශකයක් (Low GI), තන්තු හා ප්‍රතිඔක්සිකාරක ඉහළ මට්ටමක පවතී."),
        q("ශ්‍රී ලංකාවේ බෝ නොවන රෝග වැළැක්වීම සඳහා ක්‍රියාත්මක කෙරෙන 'WHO 4×4' මූලෝපායට අයත් ප්‍රධාන බෝ නොවන රෝග 4 මොනවාද?", "හෘද හා රුධිර වාහිනී රෝග, පිළිකා, නිදන්ගත ශ්වසන රෝග සහ දියවැඩියාව", "ඩෙංගු, මැලේරියාව, බරවා සහ මී උණ", "පැපොල, සරම්ප, කම්මුල්ගාය සහ රුබෙල්ලා", "ඇස් රුදාව, කසන රෝගය, දද සහ අළුහම්", "මෙම රෝග 4ම දුම්කොළ, අහිතකර ආහාර, ව්‍යායාම මඳකම හා මත්පැන් යන පොදු අවදානම් සාධක 4ට බැඳී ඇත."),
        q("නිවසේ පරිසරය මදුරුවන්ගෙන් තොරව තබා ගැනීමට හා ආරක්ෂිත ජලය රැස් කිරීමට වැසි ජල ටැංකි සම්බන්ධයෙන් අනුගමනය කළ යුතු ක්‍රමය කුමක්ද?", "ටැංකියේ මුව කුඩා දැලකින් හෝ පියනකින් හොඳින් වසා තැබීම හා කීට භක්ෂක මසුන් දැමීම", "ටැංකිය සම්පූර්ණයෙන් විවෘතව තැබීම", "පෙට්‍රල් වත් කිරීම", "ටැංකියේ අඩිය සිදුරු කිරීම", "මදුරුවන්ට ජලය මතුපිට බිත්තර දැමීම වැළැක්වීමෙන් ගෘහස්ථ ජල ටැංකි ආරක්ෂිත වේ."),
        q("ප්‍රජාව තුළ වැඩිහිටි ජනගහනය (Elderly Population) ඉහළ යාමත් සමග ඔවුන්ගේ කායික හා මානසික සෞඛ්‍යය රැකගැනීමට සමාජය කළ යුත්තේ කුමක්ද?", "නිතිපතා සායනික පරීක්ෂණ, පවුලේ ආදරණීය රැකවරණය, සැහැල්ලු ව්‍යායාම හා සමාජ සහභාගීත්වය සැලසීම", "ඔවුන්ව තනිව කාමරයක හුදකලා කිරීම", "වෛද්‍ය සායන නතර කිරීම", "අධික මේද ආහාර ලබාදීම", "සක්‍රීය හා ගෞරවනීය වැඩිහිටි වියක් (Active Aging) ගත කිරීමට පවුලේ හා ප්‍රජාවේ සහයෝගය අත්‍යවශ්‍ය වේ."),
        q("ශ්‍රී ලංකාවේ දේශීය වෙදකම හා ආයුර්වේද සේවාවන් විධිමත්ව පවත්වාගෙන යාම සඳහා ක්‍රියාත්මක වන රාජ්‍ය ආයතන පද්ධතිය කුමක්ද?", "දේශීය වෛද්‍ය දෙපාර්තමේන්තුව හා දිවයින පුරා පිහිටි රජයේ ආයුර්වේද රෝහල් හා මධ්‍යම බෙහෙත් ශාලා", "පොලිස් දෙපාර්තමේන්තුව", "වරාය අධිකාරිය", "කෘෂිකර්ම බැංකුව", "ශ්‍රී ලංකාවේ බටහිර සෞඛ්‍ය සේවයට සමාන්තරව නොමිලේ රජයේ ආයුර්වේද රෝහල් ජාලයක්ද මහජනතාවට සේවය සපයයි."),
        q("හෙළ වෙදකමේදී මෙන්ම නූතන වෛද්‍ය විද්‍යාවේදීද 'රෝගයක් සෑදුණු පසු ප්‍රතිකාර කරනවාට වඩා රෝගය ඇතිවීම වළක්වා ගැනීම ශ්‍රේෂ්ඨය' යන මූලධර්මය හඳුන්වන්නේ කෙසේද?", "රෝග නිවාරණ මූලධර්මය (Prevention is Better than Cure)", "ශල්‍යකර්ම මූලධර්මය", "ආපදා කළමනාකරණය", "පුනරුත්ථාපනය", "සෞඛ්‍ය සම්පන්න ආහාර, ව්‍යායාම, පිරිසිදු පරිසරය හා මානසික සුවතාව රෝග නිවාරණයේ ප්‍රධාන කුළුණු වේ."),
        q("බෝ නොවන රෝගයකින් පෙළෙන පුද්ගලයෙකු වෛද්‍ය උපදෙස්වලින් තොරව තම දෛනික ඖෂධ (උදා අධි රුධිර පීඩන හෝ දියවැඩියා පෙති) නතර කිරීමේ භයානක ප්‍රතිඵලය කුමක්ද?", "හෘදයාබාධ, ආඝාතය හෝ වකුගඩු අකර්මණ්‍ය වීම වැනි මාරාන්තික හදිසි සංකූලතා ඇතිවීම", "රෝගය ඉබේම සුව වීම", "ශරීරය සම්පූර්ණයෙන් නිරෝගී වීම", "කිසිදු අතුරු ආබාධයක් ඇති නොවීම", "සුවයක් දැනුණද නියමිත ඖෂධ දිගටම ගැනීම නිදන්ගත රෝග පාලනය කර තබාගැනීමේ පදනමයි."),
        q("සෞඛ්‍ය සම්පන්න ශ්‍රී ලංකාවක් උදෙසා පාසල් සෞඛ්‍ය හා ශාරීරික අධ්‍යාපන විෂය ඉගෙනීමේ ප්‍රමුඛතම ඉලක්කය කුමක්ද?", "පෞද්ගලික හා ප්‍රජා සෞඛ්‍යය සුරකින, ක්‍රියාශීලී, මානසිකව ශක්තිමත් සහ රෝගවලින් තොර යහපත් පුරවැසියෙකු බිහි කිරීම", "කටපාඩම් කිරීම පමණි", "විභාග සමත් වීම පමණි", "වෛද්‍යවරුන් සමග තරග කිරීම", "පන්ති කාමරයේදී උගන්නා සෞඛ්‍ය හා ශාරීරික අධ්‍යාපන දැනුම ජීවිත කාලය පුරාම ප්‍රායෝගිකව භාවිත කිරීම සැබෑ අරමුණයි.")
    )
}
